UPDATE public.contract_templates SET content_html = $RKZ$<div class="contract-document"><style>
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600;700;800;900&family=Geist+Mono:wght@400;500;600&display=swap');
.contract-document{--ink:#000;--ink-2:#111;--muted:#6B6B70;--muted-2:#9A9A9F;--line:#E5E5E5;--line-2:#D1D1D1;--paper:#FFF;--soft:#F5F5F5;font-family:'Geist','Inter',system-ui,sans-serif;font-feature-settings:'ss01','cv11';color:var(--ink);background:var(--paper);line-height:1.7;font-size:11pt;letter-spacing:.005em;font-weight:400;}
.contract-document *{box-sizing:border-box;}
.rk-page{background:#fff;padding:64px 72px;border:1px solid var(--line);margin-bottom:24px;position:relative;}
.rk-cover{padding:0;border:none;overflow:hidden;background:#fff;}
.rk-cover-top{background:#000;color:#fff;padding:96px 72px 72px;position:relative;}
.rk-cover-mark{display:flex;align-items:center;gap:14px;margin-bottom:96px;}
.rk-cover-mark .dot{width:10px;height:10px;background:#fff;border-radius:50%;}
.rk-cover-mark .label{font-size:9pt;font-weight:600;letter-spacing:.4em;text-transform:uppercase;color:#fff;}
.rk-cover-eyebrow{font-size:9pt;font-weight:500;letter-spacing:.4em;text-transform:uppercase;color:#fff;opacity:.65;margin-bottom:28px;}
.rk-cover h1{font-family:'Geist','Inter',sans-serif;font-size:54pt;line-height:1.02;font-weight:700;margin:0 0 24px;letter-spacing:-.02em;color:#fff;}
.rk-cover h1 em{font-style:italic;font-weight:500;}
.rk-cover-sub{font-size:11pt;line-height:1.6;color:#fff;opacity:.8;max-width:520px;margin:0 0 40px;}
.rk-cover-rule{width:64px;height:2px;background:#fff;margin-bottom:36px;}
.rk-cover-bottom{background:#fff;padding:48px 72px 72px;}
.rk-cover-meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:32px 48px;margin-bottom:48px;}
.rk-cover-meta .item .k{font-size:8pt;font-weight:600;letter-spacing:.28em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;}
.rk-cover-meta .item .v{font-family:'Geist','Inter',sans-serif;font-size:14pt;font-weight:600;color:var(--ink);line-height:1.3;}
.rk-cover-footer{display:flex;justify-content:space-between;align-items:center;padding-top:24px;border-top:1px solid var(--ink);font-size:8.5pt;letter-spacing:.28em;text-transform:uppercase;color:var(--ink);}
.rk-toc{margin-bottom:56px;}
.rk-toc h3{font-family:'Geist','Inter',sans-serif;font-size:9pt;font-weight:600;letter-spacing:.4em;text-transform:uppercase;color:var(--ink);margin:0 0 24px;padding-bottom:14px;border-bottom:2px solid var(--ink);}
.rk-toc ol{list-style:none;counter-reset:toc;padding:0;margin:0;}
.rk-toc ol li{counter-increment:toc;display:flex;align-items:baseline;gap:14px;padding:12px 0;border-bottom:1px solid var(--line);font-size:10pt;}
.rk-toc ol li::before{content:counter(toc,decimal-leading-zero);font-family:'Geist','Inter',sans-serif;font-size:12pt;font-weight:600;color:var(--ink);min-width:36px;}
.rk-toc ol li .t{flex:1;color:var(--ink);font-weight:500;}
.rk-toc ol li .p{font-size:9pt;letter-spacing:.2em;color:var(--muted);}
.rk-section{margin-bottom:48px;}
.rk-section-head{display:flex;align-items:flex-start;gap:24px;padding-bottom:20px;border-bottom:2px solid var(--ink);margin-bottom:28px;}
.rk-section-num{font-family:'Geist','Inter',sans-serif;font-size:36pt;font-weight:700;line-height:1;color:var(--ink);letter-spacing:-.02em;}
.rk-section-titles{flex:1;}
.rk-section-titles .eyebrow{font-size:8.5pt;font-weight:600;letter-spacing:.32em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;}
.rk-section-titles h2{font-family:'Geist','Inter',sans-serif;font-size:22pt;font-weight:700;margin:0;line-height:1.15;color:var(--ink);letter-spacing:-.015em;}
.contract-document p{margin:0 0 14px;color:var(--ink-2);text-align:justify;}
.contract-document strong{color:var(--ink);font-weight:600;}
.rk-clause{display:grid;grid-template-columns:140px 1fr;gap:18px;padding:14px 0;border-bottom:1px solid var(--line);}
.rk-clause:last-child{border-bottom:none;}
.rk-clause-num{font-family:'Geist','Inter',sans-serif;font-size:10pt;font-style:italic;font-weight:600;color:var(--ink);padding-top:2px;text-transform:uppercase;letter-spacing:.06em;}
.rk-clause p{margin:0 0 8px;}
.rk-clause p:last-child{margin-bottom:0;}
.rk-clause ul, .rk-clause ol{margin:8px 0;padding-left:20px;}
.rk-clause li{margin-bottom:6px;color:var(--ink-2);}
.rk-parties{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:24px 0;}
.rk-party{border:1px solid var(--ink);padding:24px;}
.rk-party .role{font-size:8pt;font-weight:600;letter-spacing:.32em;text-transform:uppercase;color:#fff;background:#000;padding:6px 10px;display:inline-block;margin-bottom:14px;}
.rk-party .name{font-family:'Geist','Inter',sans-serif;font-size:16pt;font-weight:600;color:var(--ink);margin-bottom:14px;line-height:1.2;}
.rk-party dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:6px 14px;}
.rk-party dt{font-size:8pt;font-weight:600;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);padding-top:2px;}
.rk-party dd{margin:0;font-size:9.5pt;color:var(--ink-2);}
.rk-pullquote{font-family:'Geist','Inter',sans-serif;font-size:13pt;font-style:italic;font-weight:500;line-height:1.45;color:var(--ink);border-left:3px solid var(--ink);padding:8px 0 8px 22px;margin:24px 0;max-width:90%;}
.rk-pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--ink);margin:24px 0;}
.rk-pillar{padding:22px 20px;border-right:1px solid var(--line);background:#fff;}
.rk-pillar:last-child{border-right:none;}
.rk-pillar .num{font-family:'Geist','Inter',sans-serif;font-size:22pt;font-weight:700;color:var(--ink);line-height:1;margin-bottom:12px;}
.rk-pillar .name{font-size:9pt;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--ink);margin-bottom:8px;}
.rk-pillar .desc{font-size:9.5pt;color:var(--muted);line-height:1.5;}
.rk-hero{background:#000;color:#fff;padding:40px 36px;margin:24px 0;}
.rk-hero .label{font-size:8.5pt;font-weight:600;letter-spacing:.4em;text-transform:uppercase;color:#fff;opacity:.7;margin-bottom:16px;}
.rk-hero .total{font-family:'Geist','Inter',sans-serif;font-size:42pt;font-weight:700;color:#fff;line-height:1;letter-spacing:-.02em;margin-bottom:8px;}
.rk-hero .total-words{font-style:italic;font-size:10.5pt;color:#fff;opacity:.75;margin-bottom:28px;}
.rk-hero-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding-top:24px;border-top:1px solid rgba(255,255,255,.25);}
.rk-hero-grid .k{font-size:8pt;font-weight:600;letter-spacing:.28em;text-transform:uppercase;color:#fff;opacity:.7;margin-bottom:6px;}
.rk-hero-grid .v{font-family:'Geist','Inter',sans-serif;font-size:13pt;font-weight:600;color:#fff;}
.rk-notice{margin:24px 0;padding:22px 24px;border:1px solid var(--ink);background:#fff;display:grid;grid-template-columns:auto 1fr;gap:20px;align-items:start;}
.rk-notice .icon{width:40px;height:40px;background:#000;color:#fff;display:flex;align-items:center;justify-content:center;font-family:'Geist','Inter',sans-serif;font-size:20pt;font-weight:700;line-height:1;flex-shrink:0;}
.rk-notice .body .t{font-size:8.5pt;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--ink);margin-bottom:8px;}
.rk-notice .body p{margin:0;font-size:10pt;color:var(--ink-2);}
.rk-postal{margin:18px 0;padding:18px 22px;background:var(--soft);border-left:3px solid var(--ink);font-size:10pt;}
.rk-postal .t{font-size:8.5pt;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--ink);margin-bottom:10px;}
.rk-postal dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:4px 14px;}
.rk-postal dt{font-weight:600;color:var(--muted);font-size:9pt;}
.rk-postal dd{margin:0;color:var(--ink-2);font-size:10pt;}
.rk-sign-block{margin-top:64px;padding-top:40px;border-top:2px solid var(--ink);}
.rk-sign-intro{font-family:'Geist','Inter',sans-serif;font-size:12pt;font-style:italic;color:var(--ink-2);text-align:center;margin-bottom:48px;}
.rk-sign-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-bottom:32px;}
.rk-sign{text-align:center;}
.rk-sign .line{border-top:1.5px solid var(--ink);margin-bottom:14px;padding-top:14px;}
.rk-sign .role{font-size:8.5pt;font-weight:700;letter-spacing:.32em;text-transform:uppercase;color:var(--ink);margin-bottom:6px;}
.rk-sign .name{font-family:'Geist','Inter',sans-serif;font-size:13pt;font-weight:700;color:var(--ink);}
.rk-sign .doc{font-size:9pt;color:var(--muted);margin-top:6px;}
.rk-footer{margin-top:48px;padding-top:24px;border-top:1px solid var(--ink);display:flex;justify-content:space-between;align-items:center;font-size:8.5pt;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);}
.rk-footer .brand{font-family:'Geist','Inter',sans-serif;font-size:13pt;font-style:italic;font-weight:700;letter-spacing:.04em;text-transform:none;color:var(--ink);}
@media print{.contract-document{background:#fff;}.rk-page{box-shadow:none;border:none;padding:32mm 24mm;}.rk-cover-top,.rk-hero,.rk-notice .icon,.rk-party .role{-webkit-print-color-adjust:exact;print-color-adjust:exact;}.rk-section{page-break-inside:avoid;}}
</style><div class="rk-page rk-cover"><div class="rk-cover-top"><div class="rk-cover-mark"><span class="dot"></span><span class="label">Rykas Mentoring</span></div><div class="rk-cover-eyebrow">Instrumento Particular</div><h1>Contrato de<br/>Prestação de<br/>Serviços <em>Especializados</em></h1><p class="rk-cover-sub">Mentoria em grupo estruturada pelo método exclusivo TRIP ON AIR — 3P1R&reg; (Eternum Mentoring Club).</p><div class="rk-cover-rule"></div></div><div class="rk-cover-bottom"><div class="rk-cover-meta"><div class="item"><div class="k">Contratante</div><div class="v">{{CLIENT_NAME}}</div></div><div class="item"><div class="k">Documento</div><div class="v">{{CLIENT_DOCUMENT}}</div></div><div class="item"><div class="k">Programa</div><div class="v">{{PRODUCT_NAME}}</div></div><div class="item"><div class="k">Investimento Total</div><div class="v">{{TOTAL_VALUE}}</div></div><div class="item"><div class="k">Vigência</div><div class="v">{{CONTRACT_DURATION}}</div></div><div class="item"><div class="k">Data de Celebração</div><div class="v">{{CONTRACT_DATE}}</div></div></div><div class="rk-cover-footer"><span>Confidencial &middot; Documento Particular</span><span>{{CONTRACT_YEAR}}</span></div></div></div><div class="rk-page"><div class="rk-toc"><h3>Sumário</h3><ol><li><span class="t">Das Partes Contratantes</span><span class="p">02</span></li><li><span class="t">Do Objeto</span><span class="p">03</span></li><li><span class="t">Do Procedimento Utilizado na Prestação dos Serviços</span><span class="p">04</span></li><li><span class="t">Das Responsabilidades do Contratado</span><span class="p">05</span></li><li><span class="t">Das Responsabilidades do Contratante</span><span class="p">06</span></li><li><span class="t">Do Investimento</span><span class="p">07</span></li><li><span class="t">Da Informação</span><span class="p">08</span></li><li><span class="t">Do Inadimplemento</span><span class="p">09</span></li><li><span class="t">Da Desistência e da Multa</span><span class="p">10</span></li><li><span class="t">Da Interrupção do Contrato</span><span class="p">11</span></li><li><span class="t">Da Vigência e Prazos</span><span class="p">12</span></li><li><span class="t">Da Rescisão Contratual</span><span class="p">13</span></li><li><span class="t">Da Relação Contratual</span><span class="p">14</span></li><li><span class="t">Da Não Relação Empregatícia</span><span class="p">15</span></li><li><span class="t">Das Disposições Gerais</span><span class="p">16</span></li><li><span class="t">Do Sistema Clínica Ryka</span><span class="p">17</span></li><li><span class="t">Da Assinatura Eletrônica</span><span class="p">18</span></li><li><span class="t">Da Autorização ao Uso de Imagem</span><span class="p">19</span></li><li><span class="t">Do Foro</span><span class="p">20</span></li></ol></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">I</div><div class="rk-section-titles"><div class="eyebrow">Preâmbulo</div><h2>Das Partes Contratantes</h2></div></div><p>Pelo presente contrato particular, o usuário a seguir signatário e abaixo qualificado, adiante denominado <strong>CONTRATADO</strong>, vem firmar o Contrato de Prestação de Serviços Especializados por Prazo Determinado com a parte abaixo qualificada como <strong>CONTRATANTE</strong>, mediante as cláusulas e condições a seguir estabelecidas.</p><div class="rk-parties"><div class="rk-party"><div class="role">Contratada</div><div class="name">Eternum Mentoring Club Ltda</div><dl><dt>Nome Fantasia</dt><dd>Eternum Club</dd><dt>CNPJ</dt><dd>53.844.206/0001-64</dd><dt>Sede</dt><dd>Avenida Copacabana, 325, Sala 207 &mdash; Dezoito do Forte Empresarial &mdash; Barueri/SP &mdash; CEP 06.472.001</dd><dt>Representante</dt><dd>Everton Pieri Demarchi dos Santos</dd></dl></div><div class="rk-party"><div class="role">Contratante</div><div class="name">{{CLIENT_NAME}}</div><dl><dt>CPF/CNPJ</dt><dd>{{CLIENT_DOCUMENT}}</dd><dt>Endereço</dt><dd>{{CLIENT_ADDRESS}}</dd><dt>E-mail</dt><dd>{{CLIENT_EMAIL}}</dd><dt>Telefone</dt><dd>{{CLIENT_PHONE}}</dd></dl></div><div class="rk-party" style="grid-column:1/-1;"><div class="role">Faturamento &middot; Nota Fiscal</div><div class="name">{{RAZAO_SOCIAL}}</div><dl><dt>Nome Fantasia</dt><dd>{{NOME_FANTASIA}}</dd><dt>CNPJ/CPF</dt><dd>{{CNPJ}}</dd><dt>Insc. Municipal</dt><dd>{{INSCRICAO_MUNICIPAL}}</dd><dt>Insc. Estadual</dt><dd>{{INSCRICAO_ESTADUAL}}</dd><dt>Endereço</dt><dd>{{RUA}}, {{NUMERO}} {{COMPLEMENTO}} &mdash; {{BAIRRO}}, {{CIDADE}}/{{ESTADO}} &mdash; CEP {{CEP}}</dd><dt>E-mail NF</dt><dd>{{EMAIL}}</dd><dt>Telefone</dt><dd>{{CELULAR}}</dd></dl></div></div><div class="rk-pullquote">As partes declaram ter pleno conhecimento e capacidade jurídica para celebrar o presente contrato, comprometendo-se a cumpri-lo integralmente.</div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">II</div><div class="rk-section-titles"><div class="eyebrow">Do Objeto</div><h2>Cláusula Primeira</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 1ª</span><p>O <strong>CONTRATADO</strong> oferecerá ao <strong>CONTRATANTE</strong> a mentoria em grupo denominada <strong>RYKAS MENTORING</strong>, direcionada ao gerenciamento comportamental e administrativo do <strong>CONTRATANTE</strong>, demonstrando um caminho claro e prático para quem deseja ser acima da média, tendo como duração do presente instrumento o plano escolhido e definido pelo <strong>CONTRATANTE</strong>, sendo o projeto realizado de forma totalmente remota e direta, diante dos métodos estipulados e de desenvolvimento próprio, denominado <strong>TRIP ON AIR — 3P1R (ETERNUM MENTORING CLUB)</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>O <strong>CONTRATANTE</strong>, a partir da assinatura deste instrumento, terá disponibilizado o acesso a todas as informações sobre os serviços que serão prestados na mentoria em grupo ora denominada <strong>RYKAS MENTORING</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>O plano <strong>RYKAS MENTORING</strong> seguirá uma lógica de 3 (três) passos:</p><div class="rk-pillars"><div class="rk-pillar"><div class="num">01</div><div class="name">Primeiro Passo</div><div class="desc">Escolha do público mais pagador e interessado possível, unido à escolha do produto a vender a esse público para que a venda seja mais fácil possível.</div></div><div class="rk-pillar"><div class="num">02</div><div class="name">Segundo Passo</div><div class="desc">Como apresentar esse produto de forma persuasiva, com a comunicação chegando ao público da maneira mais eficiente possível.</div></div><div class="rk-pillar"><div class="num">03</div><div class="name">Terceiro Passo</div><div class="desc">Como fazer a venda incluindo outros produtos para aumentar o ticket médio, gerar indicações e preparar o cliente para comprar de forma recorrente pelo maior tempo possível.</div></div></div></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>Todos os horários informados no presente contrato ou previamente agendados entre as partes serão realizados mediante o <strong>HORÁRIO OFICIAL DE BRASÍLIA</strong>.</p></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">III</div><div class="rk-section-titles"><div class="eyebrow">Do Procedimento</div><h2>Cláusulas Segunda &amp; Terceira</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 2ª</span><p>O <strong>CONTRATADO</strong> prestará os serviços objeto deste instrumento de forma remota, em grupo, pela plataforma de aulas <strong>EXCLUSIVAS</strong> do método, alinhadas com o processo <strong>RYKAS MENTORING</strong>, e através dos aplicativos <strong>WhatsApp, Telegram e/ou Instagram</strong>, conforme orientações do <strong>CONTRATADO</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>O <strong>CONTRATADO</strong> desempenhará os serviços de mentoria em grupo em 1 (um) dia da semana pré-determinado, sendo ele <strong>quinta-feira, ao vivo às 07:00</strong>, período matutino, horário de Brasília. Caso a CONTRATADA venha a alterar a data, avisará previamente.</p><ul><li><strong>I —</strong> As mentorias em grupo somente serão realizadas em dias úteis; em feriados Municipais, Estaduais ou Federais, não serão realizadas.</li><li><strong>II —</strong> Na mentoria em grupo o <strong>CONSULTOR</strong> fará uma intervenção no negócio de uma empresária.</li><li><strong>III —</strong> A critério da CONTRATADA, o CONTRATANTE poderá ser convidado a participar como <strong>MENTORADO</strong> em alguma das mentorias.</li><li><strong>IV —</strong> O CONTRATANTE terá acesso ao módulo <strong>RYKAS MENTORING</strong>.</li><li><strong>V —</strong> O CONTRATANTE terá acesso às <strong>MENTORIAS GRAVADAS</strong> atuais.</li><li><strong>VI — BÔNUS:</strong> acesso ao <strong>ANJO CONSULTOR</strong> — canal ativo via WhatsApp com consultores disponíveis (em dias úteis, horário comercial) para tirar dúvidas sobre as mentorias e auxiliar na implementação da metodologia.</li></ul></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>Para devido cumprimento do projeto, alinhadas com o processo RYKAS MENTORING, o CONTRATANTE terá acesso às aulas gravadas da <strong>COMUNIDADE ESTÉTICA RYKA</strong> incluídas na plataforma indicada pelo CONTRATADO, conforme metodologia própria e exclusiva da Eternum Mentoring Club.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>Fica estipulado entre as partes que o objeto deste contrato se destina, exclusivamente, à mentoria em grupo para desenvolvimento comportamental empreendedor do(a) CONTRATANTE e à educação de gerenciamento de seu empreendimento. Não estão contemplados aqui outros produtos ou estratégias comerciais para demais serviços prestados pelo(a) CONTRATANTE, exceto se acordado entre as partes.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>Fica determinado que durante os meses de <strong>dezembro e janeiro</strong> não ocorrerão as mentorias online em grupo durante 15 (quinze) dias, subsequentes ou não, não sendo possível à CONTRATANTE agendar mentorias durante as datas informadas pelo CONTRATADO.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 5º</span><p>Referente aos dias do parágrafo anterior, o CONTRATADO informará com antecedência mínima de <strong>20 (vinte) dias</strong> as datas em que as mentorias online não ocorrerão.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 3ª</span><p>Ciente o(a) CONTRATANTE de que a metodologia objeto deste instrumento tem como objetivo o auxílio no gerenciamento das clínicas, compromete-se a se empenhar para cumprir com o método desenvolvido pelo CONTRATADO, seguindo de forma <strong>INTEGRAL</strong> as recomendações estabelecidas, sendo os resultados diretamente proporcionais ao cumprimento desses preceitos.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>A natureza do contrato é de <strong>OBRIGAÇÃO DE MEIO</strong>, sendo que a cláusula de melhores esforços (<em>Best Efforts</em>) faz com que CONTRATANTE e CONTRATADO procedam com os melhores esforços, dentro dos limites de que dispõem, na execução da prestação de serviços ou para solucionar possíveis controvérsias acerca da interpretação deste instrumento.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>O CONTRATANTE autoriza que as reuniões realizadas presenciais e também via <strong>WhatsApp e/ou Zoom</strong> sejam <strong>gravadas</strong> pelo CONTRATADO, declarando-se ciente desta informação.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>O CONTRATANTE responsabiliza-se integralmente pelas alterações unilaterais que efetuar em seu empreendimento não aconselhadas pelo CONTRATADO.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>Na hipótese de danos a terceiros ou ao CONTRATADO em razão de informações <strong>falsas, incorretas, incompletas, não autorizadas ou não atualizadas</strong>, o CONTRATANTE será considerado o único responsável, podendo responder, dependendo do caso, pelo crime de difamação previsto no Código Penal.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 5º</span><p>O CONTRATANTE compromete-se a <strong>não</strong> reproduzir ou compartilhar as informações relacionadas ao objeto deste instrumento com terceiros, bem como tais informações não poderão ser divulgadas, publicadas ou aproveitadas por quaisquer das partes, por ação ou omissão, exceto se autorizado pelo CONTRATADO, sob pena de rescisão.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 6º</span><p>A multa pelo descumprimento da cláusula acima está determinada na Cláusula Sétima, somada à responsabilização por lucros cessantes, danos diretos, indiretos, emergentes e morais. Os envolvidos podem responder criminalmente por: (i) crime de concorrência desleal (art. 195, XI da Lei 9.279/96); (ii) divulgação de segredo (art. 153 do Código Penal).</p></div><div class="rk-clause"><span class="rk-clause-num">§ 7º</span><p>O CONTRATANTE aceita a obrigação de <strong>não competição</strong> em relação às atividades objeto deste contrato pelo prazo de <strong>5 (cinco) anos</strong>. O descumprimento sujeita o infrator às penalidades previstas na legislação brasileira, sem prejuízo de danos morais e da responsabilidade civil e criminal apuradas em regular processo.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 8º</span><p>Em caso de descumprimento de qualquer cláusula, o contrato poderá ser rescindido pelo CONTRATADO mediante simples notificação ao CONTRATANTE, podendo utilizar-se de WhatsApp, e-mail, Instagram, entre outros, bastando o comprovante de entrega para que surta efeitos.</p></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">IV</div><div class="rk-section-titles"><div class="eyebrow">Das Responsabilidades do Contratado</div><h2>Cláusula Quarta</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 4ª</span><p>O <strong>CONTRATADO</strong> compromete-se a desempenhar o rol de serviços neste instrumento acordados e designados na <strong>Cláusula Segunda</strong> e seus parágrafos, com responsabilidade e integridade, respeitando a legislação brasileira vigente e zelando pelos interesses da <strong>CONTRATANTE</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">Parágrafo Único</span><p>O serviço poderá, ao seu final, ser complementado por programas adicionais, os quais irão requerer contrato e investimentos específicos não incluídos neste instrumento.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">V</div><div class="rk-section-titles"><div class="eyebrow">Das Responsabilidades do Contratante</div><h2>Cláusulas 5ª a 10ª</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 5ª</span><p>É terminantemente proibido ao <strong>CONTRATANTE</strong> disponibilizar, utilizar ou vender, sem autorização do <strong>CONTRATADO</strong>, as técnicas, procedimentos, processos e métodos de exclusividade da CONTRATADA, mantendo-se assim a exclusividade na utilização de todos os seus procedimentos e projetos.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 6ª</span><p>O CONTRATANTE concorda que todas as informações e dados trocados em relação ao presente contrato, ou de caráter operacional, administrativo ou de colaboração, deverão ser tratados como <strong>confidenciais, sigilosos e restritos</strong>, sempre e a qualquer tempo. Tais dados não poderão ser fornecidos, revelados ou mencionados a terceiros, em qualquer hipótese, nem divulgados, publicados ou aproveitados pelo CONTRATANTE, por ação ou omissão, exceto se autorizado.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 7ª</span><p>O CONTRATANTE, seus empregados, colaboradores, prestadores de serviços e prepostos utilizarão os dados, expertise e informações fornecidos pelo CONTRATADO tão somente para a execução dos fins estipulados neste instrumento, obrigando-se a cientificar os receptores sobre a natureza confidencial das informações. A violação acarretará: <strong>responsabilização por lucros cessantes, danos diretos, indiretos, emergentes e morais; em caso de quebra de confidencialidade ou concorrência desleal, o infrator deverá arcar com multa no montante de R$ 50.000,00 (cinquenta mil reais)</strong>, além da imediata rescisão e demais sanções legais, podendo incorrer no crime de concorrência desleal (art. 195, XI da Lei 9.279/96).</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 8ª</span><p>A cláusula de confidencialidade permanecerá em vigor, vinculando o CONTRATANTE, seus empregados, colaboradores, prestadores e prepostos, por <strong>5 (cinco) anos após o término</strong> deste contrato, sob pena de liquidação dos danos sofridos por concorrência desleal, ensejando indenização à parte vitimada por danos patrimoniais e morais.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 9ª</span><p>O CONTRATANTE aceita a obrigação de <strong>não competição</strong> em relação às atividades do CONTRATADO, objeto deste contrato, pelo prazo de <strong>5 (cinco) anos</strong>. O descumprimento sujeitará o CONTRATANTE ao pagamento da multa estipulada na Cláusula Sétima, além das demais penalidades legais, civis e criminais.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 10ª</span><p>O CONTRATANTE se obriga a seguir os padrões de conduta vigentes na internet, abstendo-se de:</p><ul><li>(a) violar a privacidade dos outros usuários;</li><li>(b) permitir que terceiros utilizem seu acesso às mentorias e demais serviços;</li><li>(c) utilizar técnicas de invasão que violem a segurança do ambiente de treinamento e sites relacionados;</li><li>(d) agir conscientemente para destruir arquivos ou programas do ambiente;</li><li>(e) utilizar nomes e e-mails de participantes para fins comerciais;</li><li>(f) enviar mensagens obscenas ou fora dos padrões éticos e bons costumes.</li></ul></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">VI</div><div class="rk-section-titles"><div class="eyebrow">Do Investimento</div><h2>Cláusula Décima Primeira</h2></div></div><p>Como contraprestação pelos serviços contratados, o <strong>CONTRATANTE</strong> pagará ao <strong>CONTRATADO</strong> os valores e nas condições a seguir.</p><div class="rk-hero"><div class="label">Investimento Total</div><div class="total">{{TOTAL_VALUE}}</div><div class="total-words">{{TOTAL_VALUE_WORDS}}</div><div class="rk-hero-grid"><div><div class="k">Entrada</div><div class="v">{{DOWN_PAYMENT}}</div></div><div><div class="k">Parcelas</div><div class="v">{{INSTALLMENTS}}</div></div><div><div class="k">Vencimento</div><div class="v">{{DUE_DATE}}</div></div></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 11ª</span><p>O pagamento será realizado por meio de <strong>{{PAYMENT_METHOD}}</strong>, com primeiro vencimento em <strong>{{DUE_DATE}}</strong> e demais parcelas nas datas subsequentes acordadas. Caso a forma escolhida envolva <strong>cheques</strong>, aplicam-se as condições específicas do parágrafo a seguir.</p></div><div class="rk-clause"><span class="rk-clause-num">Cheques</span><p>Quando o pagamento for em cheques: deverão ser de titularidade do(a) CONTRATANTE; digitalizados e enviados ao e-mail <strong>financeiro@anjosbusiness.com.br</strong>; e remetidos via SEDEX com Aviso de Recebimento para a Caixa Postal da CONTRATADA:</p><div class="rk-postal"><div class="t">Endereço para envio dos cheques</div><dl><dt>Razão Social</dt><dd>Eternum Club Mentoring Ltda</dd><dt>Caixa Postal</dt><dd>2002</dd><dt>CEP</dt><dd>86.703-981</dd><dt>Cidade/UF</dt><dd>Arapongas / PR</dd><dt>CNPJ</dt><dd>53.844.206/0001-64</dd></dl></div><ul><li>Caso a CONTRATADA não receba os cheques nos primeiros <strong>15 (quinze) dias</strong> corridos após a assinatura, o(a) CONTRATANTE arcará com multa de alteração de contrato no valor de <strong>R$ 2.000,00 (dois mil reais)</strong>, paga junto da parcela 02.</li><li>Caso o primeiro cheque não chegue à CONTRATADA e não possa ser depositado na data acordada, o(a) CONTRATANTE deverá realizar o pagamento da parcela mediante <strong>PIX</strong>.</li></ul></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>No valor acima estão incluídos os itens descritos no projeto e objeto deste instrumento.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>A ausência do(a) CONTRATANTE às atividades presenciais (se houver) e nas mentorias, bem como a falta de cumprimento de demais obrigações de sua responsabilidade remota, <strong>não o(a) exime do pagamento</strong> do programa nas datas pactuadas.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>A solicitação para participar do projeto <strong>RYKAS MENTORING</strong>, ato que estabelece o vínculo entre as partes, dar-se-á com a assinatura deste instrumento e o pagamento integral do curso, ou, se parcelado, em modelo progressivo.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>Atrasos no pagamento acarretarão multa de <strong>5% (cinco por cento)</strong> sobre o valor da mensalidade.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">VII</div><div class="rk-section-titles"><div class="eyebrow">Da Informação</div><h2>Cláusula Décima Segunda</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 12ª</span><p>O CONTRATADO disponibilizou ao CONTRATANTE todas as informações necessárias sobre o serviço, sendo totalmente transparente quanto às suas cláusulas e termos, declarando-se o CONTRATANTE ciente e sem dúvidas quanto ao procedimento e objeto deste contrato.</p></div><div class="rk-clause"><span class="rk-clause-num">Parágrafo Único</span><p>A CONTRATADA se compromete a coletar e processar quaisquer dados pessoais do CONTRATANTE de acordo com a <strong>Lei Geral de Proteção de Dados (Lei nº 13.709/2018)</strong>. O tratamento de dados será feito para propósitos legítimos, específicos, explícitos e informados ao titular. A CONTRATADA manterá os dados sob sua titularidade pelo prazo de 5 (cinco) anos, se necessário para cumprimento de obrigações fiscais; do contrário, mediante solicitação após o encerramento do contrato, os dados poderão ser excluídos. O CONTRATANTE poderá participar de grupos e comunidades, hipótese em que reconhece que os demais integrantes poderão ter acesso a seus dados, não sendo de responsabilidade da CONTRATADA o uso por terceiros.</p></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">VIII</div><div class="rk-section-titles"><div class="eyebrow">Do Inadimplemento</div><h2>Cláusula Décima Terceira</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 13ª</span><p>Em se tratando de pagamento <strong>à vista</strong>, o início do programa ficará condicionado ao efetivo cumprimento da obrigação.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>Em pagamento a prazo, em caso de inadimplemento do CONTRATANTE, deverá incidir sobre o valor da parcela a multa pecuniária descrita na <strong>Cláusula 11ª, § 4º</strong>, acrescida de correção monetária pelo INPC/IBGE e juros de mora de <strong>1% (um por cento) ao mês</strong>, cobrados a partir da primeira parcela inadimplida.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>A inadimplência acarretará a interrupção integral dos serviços <strong>a partir de 10 (dez) dias da parcela inadimplida</strong> ou, dependendo da recusa do pagamento, a qualquer momento, dando ao CONTRATADO o direito de inserir o nome do CONTRATANTE nos órgãos de proteção ao crédito.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>Em caso de inadimplência, sendo necessária cobrança judicial, serão acrescidas as <strong>custas processuais e 20% (vinte por cento) de honorários advocatícios</strong>.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">IX</div><div class="rk-section-titles"><div class="eyebrow">Da Desistência e da Multa</div><h2>Cláusulas 15ª &amp; 16ª</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 15ª</span><p>Este instrumento é regido pelo <strong>Código Civil</strong> vigente no Brasil.</p></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 16ª</span><p>Em caso de desistência do serviço, o CONTRATANTE deverá informar o CONTRATADO por escrito, realizando requerimento de desistência com até <strong>5 (cinco) dias</strong> de antecedência.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>O CONTRATADO analisará o requerimento e os motivos da desistência, podendo optar pela aplicação da cláusula penal ou não.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>Em caso de aplicação da multa contratual (cláusula penal), conforme <strong>art. 409 do Código Civil</strong>, será aplicada da seguinte forma:</p><ul><li><strong>I —</strong> Pedido de rescisão antes do início do projeto: restituição dos valores pagos com cobrança de multa compensatória de <strong>20%</strong> sobre o valor do projeto, a título de custos operacionais (salvo caso fortuito ou força maior comprovados).</li><li><strong>II —</strong> Pedido de rescisão do 1º dia até o 1º dia do <strong>3º mês</strong>: multa compensatória de <strong>50%</strong> sobre o valor do projeto.</li><li><strong>III —</strong> Pedido de rescisão do 2º dia do 3º mês ao 1º dia do <strong>5º mês</strong>: multa compensatória de <strong>80%</strong> sobre o valor do projeto.</li><li><strong>IV —</strong> Considerando que o presente contrato tem prazo de vigência de <strong>6 (seis) meses</strong>, a partir do 2º dia do 5º mês <strong>não será possível solicitar o cancelamento</strong>, devendo a CONTRATANTE arcar com o valor total.</li><li><strong>V —</strong> Enquanto não apresentado pedido formal de cancelamento, a CONTRATANTE continuará obrigada aos pagamentos pelas mentorias ministradas, sem exceção, não havendo reembolso retroativo.</li><li><strong>VI —</strong> O CONTRATANTE não poderá rescindir alegando insatisfação com o resultado do projeto, ressaltando-se que o método e a responsabilidade do CONTRATADO são de <strong>MEIO</strong> e não de <strong>FIM</strong>.</li></ul></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>O estorno de valores pagos a maior, após a incidência da multa, ocorrerá da seguinte maneira:</p><ul><li><strong>I —</strong> Se o pagamento foi à vista: estorno à vista, em até <strong>5 (cinco) dias úteis</strong>.</li><li><strong>II —</strong> Se a prazo: estorno em parcelas, com vencimento fixado pelo CONTRATADO.</li></ul></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">X</div><div class="rk-section-titles"><div class="eyebrow">Da Interrupção do Contrato</div><h2>Cláusula Décima Sétima</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 17ª</span><p>Os serviços serão interrompidos imediatamente em caso de inadimplência dos termos da Cláusula de Desistência, sendo retomados automaticamente assim que reestabelecida a normalidade dentro das condições contratadas.</p></div><div class="rk-clause"><span class="rk-clause-num">Parágrafo Único</span><p>O requerimento de retorno será analisado, podendo ser aceito ou rejeitado de acordo com a avaliação do CONTRATADO.</p></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XI</div><div class="rk-section-titles"><div class="eyebrow">Da Vigência e Prazos</div><h2>Cláusula Décima Oitava</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 18ª</span><p>O presente instrumento terá prazo de vigência de <strong>{{CONTRACT_DURATION}}</strong>, com início em <strong>{{START_DATE}}</strong> e término em <strong>{{END_DATE}}</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>A vigência poderá não coincidir com o prazo do parcelamento; caso o CONTRATANTE tenha optado pelo parcelamento, deverá arcar com os valores nas datas acordadas, mesmo que ultrapassem a vigência do contrato.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>Qualquer modificação entre as partes será comunicada por escrito, por qualquer meio de comunicação, desde que previamente acordada.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>Caso a CONTRATANTE não esteja com nenhuma parcela atrasada e efetue o pagamento integral nas parcelas pactuadas, terá direito, como bônus, a mais <strong>6 (seis) meses</strong> do presente contrato, iniciados após o término da vigência.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>Em caso de inadimplemento ou atraso de qualquer parcela, o tempo de acesso ao bônus será cancelado pela CONTRATADA.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XII</div><div class="rk-section-titles"><div class="eyebrow">Da Rescisão Contratual</div><h2>Cláusula Décima Nona</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 19ª</span><p>A rescisão contratual poderá ser consumada a partir do <strong>1º (primeiro) mês</strong>, respeitando neste caso as multas previstas na Cláusula de Desistência deste instrumento.</p></div><div class="rk-clause"><span class="rk-clause-num">Parágrafo Único</span><p>A rescisão contratual não exime a CONTRATANTE de arcar com eventuais pendências financeiras decorrentes deste contrato.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XIII</div><div class="rk-section-titles"><div class="eyebrow">Da Relação Contratual</div><h2>Cláusula Vigésima</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 20ª</span><p>A relação objeto deste instrumento, entre o <strong>CONTRATADO</strong> e o <strong>CONTRATANTE</strong>, é informada de forma exclusiva na Cláusula Primeira e seguintes.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XIV</div><div class="rk-section-titles"><div class="eyebrow">Da Não Relação Empregatícia</div><h2>Cláusula Vigésima Primeira</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 21ª</span><p>Fica entendido entre as partes que, em <strong>nenhuma hipótese</strong>, os serviços aqui contratados guardam qualquer vínculo empregatício ou qualquer outro vínculo.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XV</div><div class="rk-section-titles"><div class="eyebrow">Das Disposições Gerais</div><h2>Cláusula Vigésima Segunda</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 22ª</span><p>O CONTRATADO <strong>não se responsabiliza</strong> pelos danos e prejuízos de toda e qualquer natureza que possam derivar da má utilização dos serviços contratados.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>O objeto deste contrato é <strong>individual e intransferível</strong>, não podendo o(a) CONTRATANTE, em nenhuma hipótese, transferir seu uso a terceiros.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>Os resultados dependem, primeiro, da responsabilidade, supervisão e boas orientações por parte do CONTRATADO, e, segundo, da disciplina, boas práticas e estrita obediência às recomendações por parte do(a) CONTRATANTE.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>O presente contrato constitui <strong>título executivo extrajudicial</strong>, nos termos do art. 784 do Código de Processo Civil vigente, cabendo execução em caso de não pagamento pelo CONTRATANTE.</p></div></div></div><div class="rk-page"><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XVI</div><div class="rk-section-titles"><div class="eyebrow">Do Sistema Clínica Ryka</div><h2>Cláusula Vigésima Terceira</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 23ª</span><p>Fica liberado para a CONTRATANTE o acesso à ferramenta <strong>CLÍNICA RYKA</strong> — ferramenta exclusiva de vendas dos ANJOS — por <strong>6 (seis) meses</strong> a contar da assinatura deste contrato.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>O acesso será liberado para até <strong>3 (três) usuários</strong>; caso a CONTRATANTE queira mais usuários, deverá entrar em contato para adquirir a licença adicional.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>Considerando que o sistema CLÍNICA RYKA é um <strong>bônus</strong> pela compra da RYKAS MENTORING, com o encerramento deste contrato encerra-se também o acesso ao sistema.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>Caso a CONTRATANTE tenha interesse em manter o sistema, deverá comprar diretamente com a CONTRATADA a licença de uso, considerando os preços vigentes na época da contratação.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>A CONTRATANTE terá acesso por <strong>6 (seis) meses</strong> da ferramenta <strong>PILOTO AUTOMÁTICO</strong> do sistema CLÍNICA RYKA. Após esse período o acesso será retirado, podendo, se de interesse, ser adquirido diretamente com o departamento comercial da CONTRATADA, considerando os preços vigentes.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XVII</div><div class="rk-section-titles"><div class="eyebrow">Da Assinatura Eletrônica</div><h2>Cláusula Vigésima Quarta</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 24ª</span><p>As Partes reconhecem a veracidade, autenticidade, integridade, validade e eficácia deste Contrato e seus termos, em formato eletrônico e/ou assinado por meio de certificados eletrônicos, como, por exemplo, via upload em plataformas como <strong>ZapSign, DocuSign</strong> ou similar.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>A Lei Brasileira reconhece a validade dos contratos eletrônicos conforme o disposto no <strong>art. 10, § 2º, da MP nº 2.200-2/2001</strong>, no <strong>art. 225 do Código Civil</strong> e no <strong>art. 369 do Código de Processo Civil</strong>.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>As Partes anuem, autorizam, aceitam e reconhecem como válida qualquer forma de comprovação de autoria por meio de certificados eletrônicos, ainda que não emitidos pela ICP-Brasil, sendo qualquer de tais certificados suficiente para a validade e eficácia deste Contrato e a vinculação das Partes aos seus termos.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XVIII</div><div class="rk-section-titles"><div class="eyebrow">Da Autorização ao Uso de Imagem</div><h2>Cláusula Vigésima Quinta</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 25ª</span><p>Com base na <strong>Lei nº 9.610/98</strong>, de forma inteiramente gratuita, a CONTRATANTE cede em caráter <strong>universal, total, definitivo, irrevogável e irretratável</strong> a utilização de seus direitos autorais e de sua imagem, conforme as condições seguintes.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 1º</span><p>Para fins deste termo, o CONTRATANTE entende como imagem qualquer forma de representação, inclusive a fotográfica, e o processo audiovisual que resulta da fixação de imagens com ou sem som, independentemente do suporte ou do meio utilizado para sua veiculação.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 2º</span><p>A presente cessão é feita em caráter universal, total e definitiva, por prazo indeterminado e a título gratuito, produzindo efeitos no Brasil e em qualquer lugar fora das fronteiras nacionais.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 3º</span><p>A CONTRATANTE também autoriza a <strong>Eternum Mentoring Club Ltda</strong> a utilizar amplamente a imagem cedida, a título gratuito ou oneroso, no Brasil ou no exterior, sem qualquer limitação de tempo ou modalidade, sem que caiba ao cedente participação no proveito econômico direta ou indiretamente auferido.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 4º</span><p>A CONTRATADA poderá, a seu exclusivo critério, utilizar todas as imagens livremente, bem como seus extratos, trechos ou partes, podendo adaptá-los para produção de obras audiovisuais, fotonovelas, obras científicas, literárias, peças teatrais e/ou peças publicitárias, fixá-los em qualquer suporte material, exibi-los, transmiti-los via rádio, televisão (aberta ou por assinatura), pay-tv, pay-per-view, vídeo on demand, plataformas analógicas ou digitais, internet, parques de diversão, inclusive temáticos, e qualquer outra utilização correlata.</p></div><div class="rk-clause"><span class="rk-clause-num">§ 5º</span><p>As utilizações previstas não possuem limitação de tempo ou de número de vezes, podendo ocorrer no Brasil e/ou no exterior, sem que seja devida ao cedente qualquer remuneração.</p></div></div><div class="rk-section"><div class="rk-section-head"><div class="rk-section-num">XIX</div><div class="rk-section-titles"><div class="eyebrow">Do Foro</div><h2>Cláusula Vigésima Sexta</h2></div></div><div class="rk-clause"><span class="rk-clause-num">Cláusula 26ª</span><p>Fica eleito o Foro da Comarca de <strong>Barueri/SP</strong> para dirimir quaisquer dúvidas inerentes a este instrumento e seus aditivos contratuais (se houver).</p></div><div class="rk-clause"><span class="rk-clause-num">Encerramento</span><p>E, por assim estarem de acordo, as partes firmam o presente Contrato, em <strong>02 (duas) vias</strong> de igual teor e forma, pelas testemunhas abaixo assinadas, para que produza seus devidos efeitos legais.</p></div><div class="rk-sign-block"><div class="rk-sign-intro">E, por estarem assim justas e contratadas, as partes assinam o presente instrumento.</div><p style="text-align:center;margin-bottom:48px;font-size:10pt;color:var(--muted);letter-spacing:.18em;text-transform:uppercase;">{{SIGNATURE_CITY}} &middot; {{SIGNATURE_DATE}}</p><div class="rk-sign-grid"><div class="rk-sign"><div class="line"></div><div class="role">Contratada</div><div class="name">Eternum Mentoring Club Ltda</div><div class="doc">CNPJ 53.844.206/0001-64</div></div><div class="rk-sign"><div class="line"></div><div class="role">Contratante</div><div class="name">{{CLIENT_NAME}}</div><div class="doc">{{CLIENT_DOCUMENT}}</div></div></div><div class="rk-sign-grid" style="margin-top:24px;"><div class="rk-sign"><div class="line"></div><div class="role">Testemunha 01</div><div class="name">&nbsp;</div><div class="doc">Nome &middot; CPF</div></div><div class="rk-sign"><div class="line"></div><div class="role">Testemunha 02</div><div class="name">&nbsp;</div><div class="doc">Nome &middot; CPF</div></div></div></div><div class="rk-footer"><span class="brand">Rykas Mentoring</span><span>Documento Confidencial &middot; {{CONTRACT_DATE}}</span></div></div></div></div>$RKZ$ WHERE id = '23a8cada-3181-4b92-bdf2-194e04083c39';